:root {
  color-scheme: dark;
  --bg: #0d1117;
  --bg-deep: #070a0f;
  --panel: rgba(22, 27, 38, 0.78);
  --panel-strong: #111827;
  --panel-soft: rgba(71, 95, 145, 0.13);
  --border: rgba(148, 163, 184, 0.18);
  --border-bright: rgba(64, 224, 208, 0.36);
  --text: #f8fafc;
  --muted: #9ca3af;
  --muted-2: #cbd5e1;
  --cyan: #22d3ee;
  --green: #78f6b1;
  --blue: #6ea8ff;
  --violet: #a78bfa;
  --amber: #fbbf24;
  --danger: #fb7185;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.38);
  --radius-lg: 28px;
  --radius-md: 18px;
  --radius-sm: 12px;
  --max: 1180px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 12% 8%, rgba(34, 211, 238, 0.14), transparent 30%),
    radial-gradient(circle at 80% 0%, rgba(120, 246, 177, 0.10), transparent 28%),
    linear-gradient(180deg, #0d1117 0%, #090d14 54%, #070a0f 100%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
code, pre, .mono { font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(148, 163, 184, 0.12);
  background: rgba(7, 10, 15, 0.78);
  backdrop-filter: blur(18px);
}
.nav-wrap {
  max-width: var(--max);
  margin: 0 auto;
  padding: 14px 22px;
  display: flex;
  align-items: center;
  gap: 22px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  font-weight: 780;
  letter-spacing: -0.02em;
  white-space: nowrap;
}
.logo-mark {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--green), var(--cyan));
  color: #041014;
  box-shadow: 0 0 28px rgba(34, 211, 238, 0.24);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.nav-links a {
  padding: 8px 11px;
  border-radius: 999px;
  color: var(--muted-2);
  font-size: 14px;
  transition: color .18s ease, background .18s ease;
}
.nav-links a:hover, .nav-links a.active { color: var(--text); background: rgba(148, 163, 184, 0.10); }
.utility { display: flex; align-items: center; gap: 8px; }
.search-pill, .mode-pill, .login-pill {
  border: 1px solid var(--border);
  background: rgba(15, 23, 42, 0.62);
  color: var(--muted-2);
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 13px;
}
.mode-pill { width: 38px; height: 38px; padding: 0; cursor: pointer; }
.mobile-nav-toggle { display: none; }

main { overflow: hidden; }
.section, .hero { max-width: var(--max); margin: 0 auto; padding: 82px 22px; }
.hero { padding-top: 92px; padding-bottom: 68px; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
  border: 1px solid rgba(34, 211, 238, 0.26);
  background: rgba(34, 211, 238, 0.08);
  color: #baf5ff;
  border-radius: 999px;
  padding: 7px 11px;
  font-size: 13px;
}
h1, h2, h3 { margin: 0; line-height: 1.08; letter-spacing: -0.045em; }
h1 { max-width: 850px; font-size: clamp(46px, 8vw, 92px); }
h2 { font-size: clamp(30px, 4vw, 52px); }
h3 { font-size: 22px; }
p { margin: 0; color: var(--muted-2); }
.hero p { max-width: 760px; margin-top: 22px; font-size: clamp(18px, 2vw, 21px); color: #dbeafe; }
.hero-actions, .actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 11px 16px;
  font-weight: 700;
  font-size: 14px;
  transition: transform .18s ease, border-color .18s ease, background .18s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn-primary { background: linear-gradient(135deg, var(--green), var(--cyan)); color: #031016; box-shadow: 0 12px 40px rgba(34, 211, 238, 0.22); }
.btn-secondary { background: rgba(15, 23, 42, 0.70); border-color: var(--border); color: var(--text); }
.btn-ghost { color: #baf5ff; padding-left: 0; }

.section-head { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 28px; }
.section-head p { max-width: 680px; margin-top: 12px; }
.grid { display: grid; gap: 18px; }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.card {
  position: relative;
  min-height: 160px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, rgba(17, 24, 39, 0.82), rgba(15, 23, 42, 0.52));
  box-shadow: var(--shadow);
  padding: 24px;
  overflow: hidden;
}
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 15% 0%, var(--glow, rgba(34, 211, 238, 0.12)), transparent 38%);
  pointer-events: none;
}
.card > * { position: relative; }
.card h3 { margin-bottom: 10px; }
.card p { font-size: 15px; }
.card .icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  margin-bottom: 18px;
  background: rgba(34, 211, 238, 0.12);
  border: 1px solid rgba(34, 211, 238, 0.22);
  color: var(--cyan);
}
.product-card { min-height: 300px; display: flex; flex-direction: column; }
.product-card .btn { margin-top: auto; width: fit-content; }
.product-card.apps { --glow: rgba(120, 246, 177, 0.18); }
.product-card.storefronts { --glow: rgba(34, 211, 238, 0.18); }
.product-card.agents { --glow: rgba(167, 139, 250, 0.20); }

.cli-shell {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 18px;
  align-items: start;
}
.accordion-list { display: grid; gap: 12px; }
.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgba(15, 23, 42, 0.62);
  overflow: hidden;
}
.accordion-trigger {
  width: 100%;
  border: 0;
  color: var(--text);
  background: transparent;
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
  cursor: pointer;
  text-align: left;
}
.accordion-trigger strong { display: block; font-size: 18px; }
.accordion-trigger span { display: block; color: var(--muted); font-size: 13px; margin-top: 2px; }
.chev { transition: transform .2s ease; color: var(--cyan); }
.accordion-item.active { border-color: var(--border-bright); background: rgba(34, 211, 238, 0.06); }
.accordion-item.active .chev { transform: rotate(180deg); }
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height .25s ease; }
.accordion-item.active .accordion-panel { max-height: 280px; }
.accordion-panel ol { margin: 0; padding: 0 24px 20px 42px; color: var(--muted-2); }
.accordion-panel li { margin: 8px 0; }
.code-card {
  border: 1px solid rgba(34, 211, 238, 0.22);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, rgba(3, 7, 18, 0.92), rgba(15, 23, 42, 0.82));
  box-shadow: var(--shadow);
  overflow: hidden;
}
.code-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(148, 163, 184, 0.13);
  padding: 12px;
}
.tabs { display: flex; gap: 7px; }
.tab {
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  border-radius: 999px;
  padding: 7px 11px;
  cursor: pointer;
}
.tab.active { color: #031016; background: var(--green); }
.code-label { color: var(--muted); font-size: 13px; }
pre {
  margin: 0;
  padding: 22px;
  overflow-x: auto;
  color: #d1fae5;
  font-size: 14px;
  line-height: 1.7;
}
.prompt { color: var(--cyan); user-select: none; }
.comment { color: #64748b; }

.docs-layout {
  max-width: 1360px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 278px minmax(0, 1fr);
  gap: 34px;
  padding: 34px 22px 70px;
}
.docs-layout.collapsed { grid-template-columns: 78px minmax(0, 1fr); }
.docs-sidebar {
  position: sticky;
  top: 84px;
  align-self: start;
  height: calc(100vh - 110px);
  border: 1px solid var(--border);
  border-radius: 22px;
  background: rgba(15, 23, 42, 0.66);
  backdrop-filter: blur(14px);
  padding: 14px;
  transition: width .22s ease;
  overflow: hidden;
}
.sidebar-toggle {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(148, 163, 184, 0.08);
  color: var(--text);
  padding: 10px 12px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.sidebar-title { white-space: nowrap; }
.sidebar-links { margin-top: 16px; display: grid; gap: 6px; }
.sidebar-links a {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 11px;
  border-radius: 13px;
  color: var(--muted-2);
  font-size: 14px;
}
.sidebar-links a:hover, .sidebar-links a.active { background: rgba(34, 211, 238, 0.09); color: var(--text); }
.docs-layout.collapsed .sidebar-title,
.docs-layout.collapsed .sidebar-text { display: none; }
.docs-layout.collapsed .sidebar-toggle { justify-content: center; }
.docs-main .hero { padding-top: 36px; }
.docs-section {
  scroll-margin-top: 100px;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding: 56px 0;
}
.docs-section:first-of-type { border-top: 0; }
.docs-section > p { max-width: 800px; margin-top: 12px; }
.compact-grid { margin-top: 24px; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.mini-card { min-height: 142px; border-radius: 20px; padding: 20px; box-shadow: none; }
.badge {
  display: inline-flex;
  width: fit-content;
  border: 1px solid rgba(120, 246, 177, 0.28);
  color: #bbf7d0;
  background: rgba(120, 246, 177, 0.08);
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 12px;
  margin-bottom: 14px;
}
.actor-ring {
  margin-top: 28px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.actor {
  text-align: center;
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 22px 16px;
  background: rgba(15, 23, 42, 0.68);
}
.actor .avatar {
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  margin: 0 auto 13px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(34, 211, 238, 0.18), rgba(167, 139, 250, 0.18));
  border: 1px solid rgba(34, 211, 238, 0.26);
  color: var(--cyan);
  font-weight: 800;
}
.status { color: var(--amber); border-color: rgba(251, 191, 36, 0.3); background: rgba(251, 191, 36, 0.08); }

.launch-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.community-card { min-height: 132px; }
.footer {
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  background: rgba(7, 10, 15, 0.62);
}
.footer-inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 42px 22px;
  display: grid;
  grid-template-columns: 1.2fr repeat(4, 1fr);
  gap: 26px;
}
.footer h4 { margin: 0 0 12px; font-size: 14px; }
.footer a, .footer p { display: block; color: var(--muted); font-size: 14px; margin: 7px 0; }

@media (max-width: 960px) {
  .nav-wrap { flex-wrap: wrap; }
  .mobile-nav-toggle { display: inline-flex; margin-left: auto; }
  .nav-links, .utility { display: none; width: 100%; }
  .nav-wrap.open .nav-links, .nav-wrap.open .utility { display: flex; flex-wrap: wrap; margin-left: 0; }
  .grid-3, .grid-4, .cli-shell, .launch-panel, .footer-inner { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .docs-layout { grid-template-columns: 1fr; gap: 16px; }
  .docs-layout.collapsed { grid-template-columns: 1fr; }
  .docs-sidebar { position: relative; top: 0; height: auto; }
  .docs-layout.collapsed .sidebar-links { display: none; }
  .docs-layout.collapsed .sidebar-title { display: inline; }
  .compact-grid, .actor-ring { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 620px) {
  .section, .hero { padding-left: 16px; padding-right: 16px; }
  .hero { padding-top: 62px; }
  h1 { font-size: clamp(40px, 13vw, 58px); }
  .section-head { display: block; }
  .compact-grid, .actor-ring { grid-template-columns: 1fr; }
  .card { padding: 20px; border-radius: 22px; }
  .code-toolbar { align-items: flex-start; gap: 10px; flex-direction: column; }
}
